from taf.sw.neat.utils.get_return_data import get_return_data
from taf.sw.neat.httpclient.neat_uri import SWManagerURI
from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.internal.sw.neat.client.sw_manager.v1.api_client import ApiClient
from taf.internal.sw.neat.client.sw_manager.v1.configuration import Configuration
from taf.internal.sw.neat.client.sw_manager.v1.apis.tags.images_api import ImagesApi
from taf.internal.sw.neat.client.sw_manager.v1.apis.tags.health_api import HealthApi
from taf.internal.sw.neat.client.sw_manager.v1.apis.tags.releases_api import ReleasesApi
from taf.internal.sw.neat.client.sw_manager.v1.apis.tags.contexts_api import ContextsApi
from urllib.parse import urlencode


class SwManagerV1(object):
    def __init__(self, conn_details, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.configuration.access_token = access_token
        api_client = ApiClient(configuration=self.configuration)
        self.api_client_local = ApiClientLocal(conn_details, access_token)

        self.contexts_api = ContextsApi(api_client)
        self.images_api = ImagesApi(api_client)
        self.health_api = HealthApi(api_client)
        self.releases_api = ReleasesApi(api_client)

    def get_cloud_sw_context(self, cloud_sw_id=None, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.contexts_api.contexts_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        result = get_return_data(res, raw)
        if cloud_sw_id:
            return [item for item in result['data'] if item["attributes"]['cloudSwId'] == cloud_sw_id]
        else:
            return result['data']

    def delete_cloud_sw_context(self, context_id, timeout=60):
        return self.contexts_api.contexts_context_id_delete(path_params={'context-id': context_id}, timeout=timeout)

    def create_cloud_sw_context(self, cloud_sw_id, image_id, raw=True, timeout=60):
        body = {"data":{
            "type":"contexts",
            "attributes":{
                "cloudSwId":cloud_sw_id,
                "imageUrl":"",
                "imageId":image_id
                }
            }
        }
        res = self.contexts_api.contexts_post(body=body, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw)['data']

    def get_cloud_sw_images(self, image_name=None, raw=True, timeout=60):
        res = self.images_api.images_get(skip_deserialization=raw, timeout=timeout)
        result = get_return_data(res, raw)
        if image_name:
            return [item for item in result['data'] if item["attributes"]['name'] == image_name]
        else:
            return result['data']

    def get_sw_manager_health(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.health_api.admin_health_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)['data']

    def get_sw_releases(self, raw=True, timeout=60, **kwargs):
        query_params = {}
        for key, val in kwargs.items():
            query_params[key] = val
        res = self.releases_api.releases_get(query_params=query_params, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)

    def delete_ocp_release(self, release_id, raw=True, timeout=60):
        res = self.releases_api.releases_release_id_delete(path_params={'release-id': release_id}, skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)


    def add_ocp_release(self, *, release_url, registry_metadata_url=None, registry_images_url=None, registry_namespace_id=None,
                        credentials=None, operations=None, agent_mode=False, raw=True, registry_check=True, timeout=60):
        if not credentials:
            raise ValueError("Credentials must be provided.")
        if bool(registry_metadata_url) == bool(registry_images_url):
            raise ValueError("Provide exactly one of 'registry_metadata_url' or 'registry_images_url'.")
        if registry_images_url and operations is None:
            raise ValueError("When 'registry_images_url' is provided, 'operations' cannot be None.")
        params = {}
        if operations:
            params['operations'] = operations
            if 'populate' in operations and registry_images_url:
                params['registry-namespace-id'] = registry_namespace_id
        params['agent-mode-supported'] = str(agent_mode).lower()
        params['skip-registry-check'] = str(not registry_check).lower()
        uri = f"{SWManagerURI.releases_uri}?{urlencode(params, doseq=True, safe=',')}" if params else SWManagerURI.releases_uri
        headers = {"credentials": credentials, "Content-Type": "application/json"}
        body = {
            "data": {
                "type": "releases",
                "attributes": {
                    "registryMetadataUrl": registry_metadata_url,
                    "registryImagesUrl": registry_images_url,
                    "releaseUrl": release_url
                }
            }
        }
        return self.api_client_local.send_post_request(
            uri=uri,
            json=body,
            headers=headers,
            raw=raw,
            timeout=timeout
        )
